// === Tab: mySketch ===

import java.util.Iterator;

let BACKGROUND_COLOUR = 0;                         // 0 = black, 255 = white
let MOTION_BLUR_FACTOR = 15;                       // Lower = more motion blur

let EXPLOSION_HALO_THICKNESS = 1;                    // Higher = thicker halo
let EXPLOSION_HALO_LIFESPAN = 175;                   // let long the halo lasts, lower = fade quicker
let EXPLOSION_HALO_SPEED_MIN = 2;                    // let bound used to generate speed the halo emits from its starting point, higher = faster
let EXPLOSION_HALO_SPEED_MAX = 4;                    // let bound used to generate speed the halo emits from its starting point, higher = faster

let FLOATING_PARTICLE_SIZE = 3;                      // Higher = bigger particle
let FLOATING_PARTICLE_LIFESPAN = 175;                // Lower = fade faster, higher = last longer
let FLOATING_PARTICLE_VELOCITY_LIMIT_MIN = 2;      // let bound used to generate initial particle velocity
let FLOATING_PARTICLE_VELOCITY_LIMIT_MAX = 5;        // let bound used to generate initial particle velocity

let system = new ParticleSystem();

let interval;
let colorInterval;
let colorSelection = 0;

function setup()
{
  background(BACKGROUND_COLOUR);
  createCanvas(400, 400);
}

function draw()
{
  // let blur
  noStroke();
  fill(BACKGROUND_COLOUR, MOTION_BLUR_FACTOR);
  rect(0, 0, width, height);

  // let the particle system
  system.update();


  if (interval < millis()) {
    GenerateExplosion();
    interval = millis() + int(random(750));
  }

  if (colorInterval < millis()) {
    colorSelection++;
    if (colorSelection == 5) { colorSelection = 0; }

    colorInterval = millis() + 7500 + int(random(10000));
  }
}

function mousePressed() 
{
  GenerateExplosion();
}

function GenerateExplosion()
{
  let haloColor = 0, particleColor = 0;
  switch(colorSelection) 
  {
    case 0:
      haloColor = color("#0D2B52"); //left
      particleColor = color("#FFF59E"); // right
      break;
    case 1:
      haloColor = color("#ED3D66");
      particleColor = color("#003E83");
      break;    
    case 2:
      haloColor = color("#E6ADCF");
      particleColor = color("#A90636");
      break;
    case 3:
      haloColor = color("#A6D40D");
      particleColor = color("#FFA6D9");
      break;
    case 4:
      haloColor = color("#D94D99");
      particleColor = color(255);
      break;

  }

  let count = int(random(50, 100));
  for (i = 0; i < count; i++) {
    system.FloatingParticles.add(new FloatingParticle(new PVector(width/2, height/2), particleColor)); 
  }

  system.Halos.add(new Halo(new PVector(width/2, height/2), haloColor)); 
}

function CMYKtoRGB(c, y, m, k)
{
  return color(255 * (1 - c / 100) * ( 1 - k / 100), 
    255 * (1 - m / 100) * ( 1 - k / 100), 
    255 * (1 - y / 100) * ( 1 - k / 100));
}

class ParticleSystem
{
  // let sub particles
  ArrayList<FloatingParticle> FloatingParticles = new ArrayList<FloatingParticle>();
  ArrayList<Halo> Halos = new ArrayList<Halo>();

  function update()
  {  
    // let every particle in existence
    this.updateFloatingParticles();
    this.updateHalos();
  }

  function updateFloatingParticles()
  {
    Iterator<FloatingParticle> i = FloatingParticles.iterator();
    while (i.hasNext()) {
      let f = i.next();


      f.vel.limit(f.limit);
      f.move();

      if (f.isDead()) {
        i.remove();
      } else {
        f.display();
      }
    }
  }

  function updateHalos()
  {
    Iterator<Halo> i = Halos.iterator();
    while (i.hasNext()) {
      let h = i.next();

      h.update();

      if (h.isDead()) {
        i.remove();
      } else {
        h.display();
      }
    }
  }
}

class Particle
{
  let pos;                       // let PVector vel = new PVector(0, 0);   // let PVector acc = new PVector(0, 0);   // let float mass = random(2, 2.5);       // Weight (adds more variance to movement)

  size = 2;                    // let size of particle
  c;                           // let int lifespan = 400;                // let lifespan, decremented every update, particle destroyed when 0

  exploded = false;          // let flag stops the firework from exploding multiple times
  subParticle = false;       // let flag is used by all derived particle types, it stops them from
  // from exploding the way the initial particle/firework does

  constructor(p)
  {
    pos = new PVector (p.x, p.y); 
    acc = new PVector (random(-0.1, 0.1), 0);
    c = color(255, 255, 255);
  }

  function move()
  {
    vel.add(acc); // let acceleration
    pos.add(vel); // let our speed vector to our position 
    acc.mult(0);

    // let particle lifespan
    lifespan--;
  }

  function applyForce(force) 
  {
    var f = PVector.div(force, mass);
    acc.add(f);
  }

  function display()
  {
    // let dim the colour of the particle as the lifespan decreases 
    fill(c, map(lifespan, 0, FLOATING_PARTICLE_LIFESPAN, 0, 255));
    ellipse(pos.x, pos.y, size, size);
  }

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }
}

class FloatingParticle extends Particle
{
  limit;

  constructor(p, _c)
  {
    super(p);

    this.c = _c;//color(random(200, 255), random(200, 255), 0);
    this.subParticle = true;
    this.acc = PVector.random2D();
    this.applyForce(PVector.random2D());
    this.limit = random(FLOATING_PARTICLE_VELOCITY_LIMIT_MIN, FLOATING_PARTICLE_VELOCITY_LIMIT_MAX);
    this.lifespan = FLOATING_PARTICLE_LIFESPAN;
    this.size = random(1, FLOATING_PARTICLE_SIZE + 3);
  }
}

class Halo
{
  c;
  pos;
  size = EXPLOSION_HALO_THICKNESS;
  speed;
  lifespan = EXPLOSION_HALO_LIFESPAN;

  constructor(start, colour)
  {
    pos = start;
    c = colour;
    speed = random(EXPLOSION_HALO_SPEED_MIN, EXPLOSION_HALO_SPEED_MAX);
  }

  function update()
  {
    size = size + speed;
    lifespan--;
  }

  function display()
  { 
    strokeWeight(6);
    stroke(c, map(lifespan, 0, EXPLOSION_HALO_LIFESPAN, 0, 255));
    noFill();
    ellipse(pos.x, pos.y, size, size);
    noStroke();

    //  for (i = 0; i < 5; i++) {
    //    let r = random(-2, 2);
    //    stroke(c, map(lifespan, 0, EXPLOSION_HALO_LIFESPAN, 0, 255));
    //    ellipse(pos.x, pos.y, size + int(r), size + int(r));
    //  }
  }

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }
}

